module top_module(clk, rst, duty_cycle, pwm);input clk;
  input rst;
  input [6:0] duty_cycle;
  output pwm;

  reg [31:0] counter;
  reg pwm_reg;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      counter <= 0;
      pwm_reg <= 0;
    end else begin
      counter <= counter + 1;
      if (counter >= 1000) begin
        counter <= 0;
        pwm_reg <= (counter < (duty_cycle * 10));
      end
    end
  end

  assign pwm = pwm_reg;

endmodule

