description:
Implement the Verilog module based on the following description.
Module G implements the boolean function z = ~(x & y).

// Module H can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 1.
If x = 0, y = 1, then z = 1.
If x = 0, y = 0, then z = 1.
If x = 1, y = 0, then z = 1.

// Now consider a top-level that uses two G submodules and two H submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first G submodule is connected to a two-input XOR, along with the output of the first H submodule. The second pair of G and H submodules is similarly connected to an AND gate. The output of the XOR and the AND is connected to an OR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
    input x,
    input y,
    output z);

code:
module G(
    input x,
    input y,
    output z
);
    assign z = ~(x & y);
endmodule

module H(
    input x,
    input y,
    output z
);
    assign z = 1;
endmodule

module top_module(
    input x,
    input y,
    output z
);
    wire g1_out, g2_out, h1_out, h2_out;
    wire xor_out, and_out;

    G g1(.x(x), .y(y), .z(g1_out));
    G g2(.x(x), .y(y), .z(g2_out));
    H h1(.x(x), .y(y), .z(h1_out));
    H h2(.x(x), .y(y), .z(h2_out));

    assign xor_out = g1_out ^ h1_out;
    assign and_out = g2_out & h2_out;

    assign z = xor_out | and_out;
endmodule

