description:
Implement the Verilog module based on the following description.
Module A implements the boolean function w = ~a | b.

// Module B can be described by the following simulation waveform: 

If a = 1, b = 1, then w = 0.
If a = 0, b = 1, then w = 1.
If a = 0, b = 0, then w = 0.
If a = 1, b = 0, then w = 1.

// Now consider a top-level that uses two A submodules and two B submodules. The first input of all four submodules is connect to input 'a', and the second input of all four submodules is connected to 'b'. The output of the first A submodule is connected to a two-input AND, along with the output of the first B submodule. The second pair of A and B submodules is similarly connected to an XOR gate. The output of the AND and the XOR is connected to an OR, whose output is 'w'.

// Implement this circuit in Verilog.

module top_module(
    input a,
    input b,
    output w);

code:
module A(
    input a,
    input b,
    output w
);
    assign w = ~a | b;
endmodule

module B(
    input a,
    input b,
    output w
);
    assign w = (~a & b) | (a & ~b);
endmodule

module top_module(
    input a,
    input b,
    output w
);
    wire a1_out, a2_out, b1_out, b2_out;
    wire and_out, xor_out, or_out;

    A a1(.a(a), .b(b), .w(a1_out));
    A a2(.a(a), .b(b), .w(a2_out));
    B b1(.a(a), .b(b), .w(b1_out));
    B b2(.a(a), .b(b), .w(b2_out));

    assign and_out = a1_out & b1_out;
    assign xor_out = a2_out ^ b2_out;
    assign w = and_out | xor_out;
endmodule

