module top_module(clk, reset, play, note_done, new_note);input clk, reset, play, note_done;
output reg new_note;
parameter RESET = 0, NEW_NOTE = 1, WAIT = 2, NEXT_NOTE = 3;
reg [1:0] state, nextstate;

always @(posedge clk) begin
    if(reset) state = RESET; 
    else state = nextstate;
end

always @(*) begin
    new_note = 0;
    case (state)
        RESET: begin if(play) nextstate = NEW_NOTE; else nextstate = RESET; end 
        NEW_NOTE: begin new_note = 1; nextstate = WAIT; end
        WAIT: begin
            if(play) begin
                if(note_done) nextstate = NEXT_NOTE;
                else nextstate = WAIT; end
            else nextstate = RESET;
            end
        NEXT_NOTE: nextstate = NEW_NOTE;
        default: nextstate = RESET;
    endcase
end
endmodule

