module fsm_module (
        input clk,
        input reset,
        input ctrl,
        output reg out);parameter Q0=0, Q1=1, Q2=2, Q3=3;
	reg[1:0] state, next;

	always @(posedge clk)
		if (reset) state <= Q0;
		else state <= next;


	always_comb begin
		case (state)
			Q0: next = ctrl ? Q1 : Q0;
			Q1: next = ctrl ? Q2 : Q1;
			Q2: next = ctrl ? Q3 : Q2;
			Q3: next = ctrl ? Q0 : Q3;
			default: next = 'x;
		endcase
	end

	assign out = (state == Q0) || (state == Q2);

endmodule

