module Parallel_to_serial_64(
   input                clk,
   input                rst_n,
   input                load,
   input  [63:0]        parallel_in,
   output reg           serial_out
);
    reg [63:0] shift_reg;

    always@(posedge clk or negedge rst_n)begin
        if(!rst_n) shift_reg <= 64'd0;
        else if(load) shift_reg <= parallel_in;
        else shift_reg <= {1'b0, shift_reg[63:1]};
    end

    always@(posedge clk or negedge rst_n)begin
        if(!rst_n) serial_out <= 1'b0;
        else serial_out <= shift_reg[0];
    end
endmodule

