  wire [1:0] dd; 
  assign {kind, dd, idxZ, idxX, tI} = insn; 
  always @* case (kind) 
  default: {idxY,op,valI[11:0],valI[31:12]} = { tI,{20{tI[11]}}}; 
  2'b11: {idxY,op,valI[19:0],valI[31:20]} = {8'h0,tI,{12{tI[19]}}}; 
  endcase 
  assign storing = ^dd; 
  assign loading = &dd; 
  assign deref_rhs = dd[0]; 
  assign branching = &idxZ & ~storing; 
