    if (tx_en) begin
        if (tx_bit_count == 0) begin
            tx_done <= 0;
            tx_data <= DATA_OUT;
        end else begin
            tx_data <= {1'b0, tx_data[7:1]};
        end
        tx_bit_count <= tx_bit_count + 1;
        if (tx_bit_count == 8) begin
            tx_en <= 0;
            tx_done <= 1;
            tx_bit_count <= 0;
