            if (Q0 == 0 && Q1 == 0) begin
                Q0 <= 1;
            end else if (Q0 == 1 && Q1 == 0) begin
                Q0 <= 0;
                Q1 <= 1;
            end else if (Q0 == 0 && Q1 == 1) begin
                Q0 <= 1;
                Q1 <= 1;
            end else begin
                Q0 <= 0;
                Q1 <= 0;
            end
        end
    end

