    begin
      Timer <= 32'd0;
    end
    else
    begin
      if (TimerPreset)
      begin
        Timer <= {PeriodH_i, PeriodL_i};
      end
      else if (TimerEnable)
      begin
        Timer <= Timer - 1'b1;
      end
    end  
  end

  assign TimerOvfl = (Timer == 0) ? 1'b1 : 1'b0;

endmodule

