module fsm (
        input clk,
        input reset,
        input c,
        output reg y);parameter A0=0, A1=1, A2=2, A3=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= A0;
		else 
			state <= next;


	always_comb begin
		case(state)
			A0: next = c ? A1 : A2;
			A1: next = c ? A3 : A2;
			A2: next = c ? A3 : A0;
			A3: next = c ? A1 : A0;
			default: next = 'x;
		endcase
	end

	assign y = (state == A1 || state == A3);

endmodule

