description:
Design a register transfer module that captures and forwards data from the memory stage to the write-back stage in a pipelined processor architecture. On the rising edge of the clock, if a reset signal is active, it initializes all output registers to zero. Otherwise, it transfers the input signals—specifically the write-back control signals, destination register, ALU result, and memory read data—into corresponding output registers for subsequent processing stages.
module top_module(clk, rst, WB_IN, ALUResIn, memReadIn, destIn,
                         WB_Out, ALUResOut, memReadOut,   destOut);

code:
module top_module(clk, rst, WB_IN, ALUResIn, memReadIn, destIn,
                         WB_Out, ALUResOut, memReadOut,   destOut);input clk, rst;

    input [1:0] WB_IN;
    input [4:0] destIn;
    input [31:0] ALUResIn, memReadIn;

    output reg [1:0] WB_Out;
    output reg [4:0] destOut;
    output reg [31:0] ALUResOut, memReadOut;

    always @ (posedge clk) begin
        if (rst) begin
            {WB_Out, destOut, ALUResOut, memReadOut} <= 0;
        end
        else begin
            WB_Out <= WB_IN;
            destOut <= destIn;
            ALUResOut <= ALUResIn;
            memReadOut <= memReadIn;
        end
    end
endmodule

