module traffic_light_controller (
    input clk,
    input reset,
    output reg ns_red,
    output reg ns_yellow,
    output reg ns_green,
    output reg ew_red,
    output reg ew_yellow,
    output reg ew_green);parameter NS_GREEN = 0, NS_YELLOW = 1, EW_GREEN = 2, EW_YELLOW = 3;
    reg [1:0] state, next;
    reg [5:0] timer;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= NS_GREEN;
            timer <= 0;
        end else begin
            if (timer == 59) begin
                state <= next;
                timer <= 0;
            end else begin
                timer <= timer + 1;
            end
        end
    end

    always @(*) begin
        case (state)
            NS_GREEN: begin
                ns_red = 0;
                ns_yellow = 0;
                ns_green = 1;
                ew_red = 1;
                ew_yellow = 0;
                ew_green = 0;
                next = (timer == 59) ? NS_YELLOW : NS_GREEN;
            end
            NS_YELLOW: begin
                ns_red = 0;
                ns_yellow = 1;
                ns_green = 0;
                ew_red = 1;
                ew_yellow = 0;
                ew_green = 0;
                next = (timer == 4) ? EW_GREEN : NS_YELLOW;
            end
            EW_GREEN: begin
                ns_red = 1;
                ns_yellow = 0;
                ns_green = 0;
                ew_red = 0;
                ew_yellow = 0;
                ew_green = 1;
                next = (timer == 59) ? EW_YELLOW : EW_GREEN;
            end
            EW_YELLOW: begin
                ns_red = 1;
                ns_yellow = 0;
                ns_green = 0;
                ew_red = 0;
                ew_yellow = 1;
                ew_green = 0;
                next = (timer == 4) ? NS_GREEN : EW_YELLOW;
            end
            default: next = NS_GREEN;
        endcase
    end

endmodule

